  const ev = c5View([evil]);
  ok(!/<b>x|<i>|<img/.test(vm.runInContext('statementsCardHtml()', ev) + vm.runInContext("renderBankStatementSheet({ id: 'st-e' })", ev)), 'a value is not escaped');
