  ok(/\(ui\.entryKind === 'online'\s*\? '<label class="fld">Trail’s End amount \(\$\)[\s\S]*?name="donations"[\s\S]*?: '<label class="fld">Trail’s End amount \(Heroes &amp; Helpers included\) \(\$\)<input[^']*name="sales"/.test(f), 'the wagon form');
