  const sf = { id: 'sf1', name: 'Grocery', date: '2026-10-05', blocks: [{ id: 'b1', salesCents: 4000, donationsCents: 500, salesCash: [{ reportId: 'r', cents: 1200 }] }, { id: 'b2', salesCents: 1000, donationsCents: 0 }] };
